import { useState } from "react";

const ChatBot = () => {
  const [chatHistory, setChatHistory] = useState([]);
  const [userInput, setUserInput] = useState("");
  const [audioResponse, setAudioResponse] = useState(null);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    const sentTime = getTimeOnly();
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          user_input: userInput,
          personality: "T",
          chatbotName: "이야",
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "이야", message: chatbotMessage, time: receivedTime },
      ]);

      // TTS 응답 처리
      if (data.audio) {
        setAudioResponse(data.audio);
      }
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);
    }
  };

  return (
    <div>
      <div>
        {chatHistory.map((message, index) => (
          <div key={index}>
            <strong>{message.sender}</strong>: {message.message}
          </div>
        ))}
      </div>

      <textarea
        value={userInput}
        onChange={(e) => setUserInput(e.target.value)}
      />
      <button onClick={handleSendMessage}>Send</button>

      {audioResponse && (
        <div>
          <audio controls autoPlay>
            <source
              src={`data:audio/mp3;base64,${audioResponse}`}
              type="audio/mp3"
            />
          </audio>
        </div>
      )}
    </div>
  );
};
